head.script:
// 화면 리사이징

scwin.gIsurCd;
scwin.gSeq;
scwin.gComNm;
scwin.contnId;
scwin.gDate;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        // 패널라운드 처리
        $c.libRoundPanel.PanelToGroupBox(panel_1);
        $c.stf.comboCbDataSetPeriod(cmb_PeriodTp);
        edt_SDate.setValue("19000101");
        edt_EDate.setValue($c.ut.cGetToday("yyyymmdd"));
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF47000.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_Excel_onclick
 * @description 「엑셀다운로드」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_Excel_onclick = function() {
    try {
        $c.stf.doLogSave('ULDSTF47000.xml', SCREN_PROCS_TP_CD_07);
        $c.data.downloadGridViewExcel(grd_Grid, {fileName: "지정자문인 제재관리 제재 사유 발생 현황", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF47000.btn_Excel_onclick" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadCompleted
 * @description dts_List 로드 완료 후처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @param {Number} rowcount 조회 건수
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadCompleted = async function(rowcount) {
    try {
        if (dts_List.errorMsg) {
            await $c.win.alert(dts_List.errorMsg);
        } else {
            $c.stf.fillGridHeaderTotalCnt(rowcount, panel_page);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF47000.dts_List_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name dts_List_OnLoadError
 * @description dts_List 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_List_OnLoadError = async function() {
    try {
        await $c.win.alert(dts_List);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF47000.dts_List_OnLoadError" });
    }
};

/**
 * @method
 * @name btn_Search_onclick
 * @description 「조회」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Search_onclick = async function() {
    try {
        if ($c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
            await scwin.search();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF47000.btn_Search_onclick" });
    }
};

/**
 * @method
 * @name btn_SDate_onclick
 * @description btn_SDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_SDate_onclick = function() {
    try {
        popUpCalendar2(edt_SDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF47000.btn_SDate_onclick" });
    }
};

/**
 * @method
 * @name btn_EDate_onclick
 * @description btn_EDate 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_EDate_onclick = function() {
    try {
        popUpCalendar2(edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF47000.btn_EDate_onclick" });
    }
};

/**
 * @method
 * @name cmb_PeriodTp_onselchange
 * @description cmb_PeriodTp onselchange 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.cmb_PeriodTp_onselchange = function() {
    try {
        const vTp = $c.cp.valueOfIndex(cmb_PeriodTp, "VALUE", cmb_PeriodTp.getSelectedIndex());
        $c.stf.setFromToDate(vTp, edt_SDate, edt_EDate);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF47000.cmb_PeriodTp_onselchange" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    url += "?SCREN_ID=" + 'ULDSTF47000.xml' + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&method=listGeneral" + "&outputMessageId=LIST_DESIGN_ADVSER_FAST_TRACK" + "&service=krx.lds.stf.listingcommon.services.ListingCommonApp" + "&queryId=lds.stf.lstmgt.designadvser.select.all" + "&{P}param01=" + edt_SDate.getValue() + "&{P}param02=" + edt_EDate.getValue() + "&{P}param03=" + edt_SDate.getValue() + "&{P}param04=" + edt_EDate.getValue() + "&{P}param05=" + edt_SDate.getValue() + "&{P}param06=" + edt_EDate.getValue() + "&{P}param07=" + edt_SDate.getValue() + "&{P}param08=" + edt_EDate.getValue() + "&{P}param09=" + edt_SDate.getValue() + "&{P}param10=" + edt_EDate.getValue() + "&{P}param11=" + edt_SDate.getValue() + "&{P}param12=" + edt_EDate.getValue() + "&{P}param13=" + edt_SDate.getValue() + "&{P}param14=" + edt_EDate.getValue() + "&{P}param15=" + edt_SDate.getValue() + "&{P}param16=" + edt_EDate.getValue() + "&{P}param17=" + edt_SDate.getValue() + "&{P}param18=" + edt_EDate.getValue() + "&{P}param19=" + edt_SDate.getValue() + "&{P}param20=" + edt_EDate.getValue() + "&{P}param21=" + edt_SDate.getValue() + "&{P}param22=" + edt_EDate.getValue() + "&{P}param23=" + edt_SDate.getValue() + "&{P}param24=" + edt_EDate.getValue() + "&{P}param25=" + edt_SDate.getValue() + "&{P}param26=" + edt_EDate.getValue();
    const sbmOptions = {
        id : "sbm_dts_List",
        action : "/listingCommon.do",
        ref : "",
        target : "dts_List=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name checkCond
 * @description check Cond 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.checkCond = async function() {
    fn_SetItemGridHeaderCheck();
    await scwin.search();
};
